-- Second sealed attempt after the first transaction fully rolled back.
-- Preserve the original immutable failure receipt and its executable source.
-- Refresh planner statistics after rebuilding each materialized view, before
-- planning dependent reports. No data/assertion/access checks are removed.
DO $tg_previous_attempt$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM tg_maintenance.metrc_quantity_precision_run WHERE run_key='metrc-quantity-20260912' AND status='failed' AND error='P0001: Precision final check timed out at "public"."v_dept_dash_cfo"') THEN RAISE EXCEPTION 'Previous precision attempt is not the observed rolled-back failure'; END IF;
