END $tg_previous_attempt$;
CREATE FUNCTION tg_maintenance.metrc_precision_sql_v2() RETURNS text LANGUAGE sql IMMUTABLE
SET search_path=pg_catalog AS $tg_sql_source$
 SELECT $tg_repair_body$-- Metrc quantity precision repair. Generated from the captured dependency catalogue.
-- This is a single transaction: any failed definition, permission, source-value or
-- row-availability assertion rolls back the entire change. No cascade drops.
-- Historical report-derived rows retain their historical provenance; restoring their
-- exact saved source quantity is not a current API population certificate.
SET LOCAL lock_timeout = '3s';
SET LOCAL search_path = public, pg_catalog;
CREATE TEMP TABLE tg_quantity_preflight (name text primary key, definition_hash text, owner_name text, acl text, options text[], extra jsonb, relation_kind text, build_order integer, populated boolean, definition text, had_row boolean) ON COMMIT DROP;
DO $tg_precision_guard$
BEGIN
 IF (select format_type(atttypid,atttypmod) from pg_attribute where attrelid='public.metrc_packages'::regclass and attname='quantity') <> 'numeric(14,3)' THEN RAISE EXCEPTION 'Quantity schema changed; re-rehearse'; END IF;
 IF (select count(*) from public.metrc_packages where raw->>'Quantity' is not null and quantity<>(raw->>'Quantity')::numeric) <> 6 THEN RAISE EXCEPTION 'Quantity discrepancy population changed; obtain new evidence'; END IF;
 IF (select md5(string_agg(jsonb_build_object('id',id,'license',license,'quantity',quantity,'raw',raw)::text,'' order by id)) from public.metrc_packages where raw->>'Quantity' is not null and quantity<>(raw->>'Quantity')::numeric) IS DISTINCT FROM 'e22944a53f041c4d9b9fb39a7fb6b1f0' THEN RAISE EXCEPTION 'Quantity source records changed; obtain new evidence'; END IF;
