INSERT INTO tg_quantity_preflight(name,definition_hash,owner_name,acl,options,extra,relation_kind,build_order,populated) VALUES ('"public"."v_finished_goods_metrc_reconciliation"','41ae1b28eb375fcae6cdbea28ae8c261','postgres','{postgres=arwdDxtm/postgres,anon=xtm/postgres,authenticated=arwdxtm/postgres,service_role=arwdDxtm/postgres,tg_desktop_reader=r/postgres,grok_writer=arwd/postgres,supabase_read_only_user=r/postgres}',ARRAY['security_invoker=true']::text[],'{"comment": "THE POINT OF THE FINISHED-GOODS IMPORT: for every Final Product Metrc tag the sales sheet claims, does our Metrc mirror agree that the package exists and that the quantity is what the sheet says? DISAGREEMENT IS THE FINDING - this view reports it and never resolves it. Read existence, quantity and identity_check as three SEPARATE questions. existence follows the owner ruling tag_missing_means_go_find_the_manifest: a tag absent from metrc_packages is looked up in metrc_rpt_package_transfers before it is ever called missing. quantity is only judged after units are made comparable, and comparison_basis states which basis was used - Metrc holds grams for 43 of these tags and each for 13, so an unnormalised comparison would invent disagreements. identity_check exists because a tag can be typed into the sheet that belongs to a completely different package: it compares the sheet strain against the item name Metrc and the manifest carry for that tag.", "columns": [["tag", null, null, null, "text"], ["source_sheet", null, null, null, "text"], ["source_row", null, null, null, "integer"], ["category", null, null, null, "text"], ["strain_flavor", null, null, null, "text"], ["production_batch", null, null, null, "text"], ["current_status", null, null, null, "text"], ["cases_available", null, null, null, "numeric"], ["coa_link", null, null, null, "text"], ["expiration_date", null, null, null, "date"], ["bulk_metrc_tag", null, null, null, "text"], ["prefill_metrc_tag", null, null, null, "text"], ["sheet_units"