INSERT INTO tg_quantity_preflight(name,definition_hash,owner_name,acl,options,extra,relation_kind,build_order,populated) VALUES ('"public"."v_stock_ageing"','ce432b0d8cc63d831df1e21ca973bd7b','postgres','{postgres=arwdDxtm/postgres,anon=xtm/postgres,authenticated=arwdxtm/postgres,service_role=arwdDxtm/postgres,tg_desktop_reader=r/postgres,grok_writer=arwd/postgres,supabase_read_only_user=r/postgres}',ARRAY['security_invoker=true']::text[],'{"comment": "Every open package with its own age against its own category policy, and its room. Ages PER PACKAGE, never per group. Seeds and concentrate do not age. Quarantine and the biomass freezer suspend the clock because material is there by decision \u2014 they held 59.65 lb of the 80.6 lb an earlier check called ageing. Nothing is hidden: a held package still shows its age and its weight, it is simply not reported as a failure to sell something nobody was selling. Agent I, 18 Aug 2026.", "columns": [["tag", null, null, null, "text"], ["item_name", null, null, null, "text"], ["category", null, null, null, "text"], ["location", null, null, null, "text"], ["license", null, null, null, "text"], ["packaged_on", null, null, null, "date"], ["days_held", null, null, null, "integer"], ["lb", null, null, null, "numeric"], ["category_ages", null, null, null, "boolean"], ["stale_after", null, null, null, "interval"], ["ageing_verdict", null, null, null, "text"], ["remnant_verdict", null, null, null, "text"], ["in_a_holding_room", null, null, null, "boolean"], ["why_held", null, null, null, "text"]], "indexes": []}'::jsonb,'v',20,true);

INSERT INTO tg_quantity_preflight(name,definition_hash,owner_name,acl,options,extra,relation_kind,build_order,populated) VALUES ('"public"."v_tag_lifecycle"','da576b0b67dab6102a81a2229e78d5cb','postgres','{postgres=arwdDxtm/postgres,anon=xtm/postgres,authenticated=arwdxtm/postgres,service_role=arwdDxtm/postgres,tg_desktop_reader=r/postgres,grok_writer=arwd/postgres,supabase_read_only_user=r/postgres}',ARRAY['security_invoker=true']::text[],'{"comment": "The seed-to-sale lifecycle for every tag. Metrc owns custody. Apex invoice identity is attached only through the exact normalized invoice number recorded in Metrc wholesale and Apex. Proximity is never a match. Invoice dollars are intentionally null at tag grain; use v_apex_invoice_truth for sales. Payment status is unavailable here until an exact invoice-grain payment surface is governed.", "columns": [["tag", null, null, null, "text"], ["item_name", null, null, null, "text"], ["category", null, null, null, "text"], ["strain", null, null, null, "text"], ["held_under_licence", null, null, null, "text"], ["stage1_harvest", null, null, null, "text"], ["stage1_cut_on", null, null, null, "date"], ["stage1_grown_in", null, null, null, "text"], ["stage1_note", null, null, null, "text"], ["stage2_packaged_on", null, null, null, "date"], ["stage2_made_from_packages", null, null, null, "text"], ["stage2_production_batch", null, null, null, "text"], ["stage3_submitted_on", null, null, null, "date"], ["stage3_result_on", null, null, null, "date"], ["stage3_lab_state", null, null, null, "text"], ["stage3_laboratory", null, null, null, "text"], ["stage3_certificate", null, null, null, "text"], ["stage3_certificate_date", null, null, null, "text"], ["stage3_coa_document", null, null, null, "text"], ["stage3_evidence_basis", null, null, null, "text"], ["stage3_note", null, null, null, "text"], ["stage4_manifest", null, null, null, "text"], ["stage4_shipped_on", null, null, null, "date"], ["stage4_shipped_to", null, null, null, "tex