INSERT INTO tg_quantity_preflight(name,definition_hash,owner_name,acl,options,extra,relation_kind,build_order,populated) VALUES ('"public"."v_harvest_tag_index"','1ed5dc5d3dda76fe6d6d7b39a8ca06c2','postgres','{postgres=arwdDxtm/postgres,anon=xtm/postgres,authenticated=arwdxtm/postgres,service_role=arwdDxtm/postgres,tg_desktop_reader=r/postgres,grok_writer=arwd/postgres,supabase_read_only_user=r/postgres}',ARRAY['security_invoker=true']::text[],'{"comment": "THE harvest -> tag bridge: one row per (harvest, tag) for every package naming the harvest in its Metrc lineage, live and closed \u2014 the inverse of v_tag_lifecycle.stage1_harvest, built 18 Aug 2026 when the owner found harvest rows dead-ending (27 harvest views, zero tag columns). Carries state, room, weight/units, lab state, certificate, and outbound manifest; blends appear under each contributing harvest (ruling D4). Filter by harvest; each tag flows on to v_tag_lifecycle / v_package_dossier. Agent I.", "columns": [["harvest", null, null, null, "text"], ["tag", null, null, null, "text"], ["item_name", null, null, null, "text"], ["category", null, null, null, "text"], ["source_state", null, null, null, "text"], ["license", null, null, null, "text"], ["room", null, null, null, "text"], ["lb", null, null, null, "numeric"], ["units", null, null, null, "numeric"], ["lab_state", null, null, null, "text"], ["certificate_id", null, null, null, "text"], ["certificate_document", null, null, null, "text"], ["outbound_manifest", null, null, null, "text"], ["shipped_to", null, null, null, "text"], ["closed", null, null, null, "boolean"], ["packaged_on", null, null, null, "date"]], "indexes": []}'::jsonb,'v',77,true);

