INSERT INTO tg_quantity_preflight(name,definition_hash,owner_name,acl,options,extra,relation_kind,build_order,populated) VALUES ('"public"."v_finished_goods_onhand"','5c3dae7e876aba1204c23911d58f7b87','postgres','{postgres=arwdDxtm/postgres,anon=xtm/postgres,authenticated=arwdxtm/postgres,service_role=arwdDxtm/postgres,tg_desktop_reader=r/postgres,grok_writer=arwd/postgres,supabase_read_only_user=r/postgres}',ARRAY['security_invoker=true']::text[],'{"comment": "FINISHED GOODS ON HAND FOR THE SALES TEAM, mirrored read-only from the owner''s Manufacturing Product Inventory workbook. Owner: \"THIS IS INVENTORY ON HAND FINISHED GOODS THIS MUST MUST MUST BE ON OUR COMMAND CENTER FOR COO AND CEO AS THEY ARE VERY INVOLVED IN SALES.\" Every row carries the FULL Metrc tag chain - bulk, pre-fill holding and final product - so any row drills to its tag per the house drilldown rule. still_in_sheet is enforced here: a row the sheet has since removed never appears as sellable. sales_confidence surfaces the Metrc reconciliation on the row itself rather than burying it in a report, because 12 of 65 final tags currently name a different product in Metrc than the sheet claims. Days to expiry and the low-stock flag are shown BOTH as the sheet computed them and as recomputed here - if the two disagree the sheet formula is stale, and that is a finding, not something to average.", "columns": [["category", null, null, null, "text"], ["product_line", null, null, null, "text"], ["current_status", null, null, null, "text"], ["strain_flavor", null, null, null, "text"], ["product_description", null, null, null, "text"], ["infusion_type", null, null, null, "text"], ["size_as_written", null, null, null, "text"], ["size_value", null, null, null, "numeric"], ["size_unit", null, null, null, "text"], ["production_batch", null, null, null, "text"], ["bulk_metrc_tag", null, null, null, "text"], ["prefill_metrc_tag", null, null, null, "text"], ["final_metrc_tag", null, null, null, "text"], ["final_tag_note", null, null, null, "text"], ["business_key", null, null, null, "text"], ["business_key_basis", null, null, null, "text"], ["cases_available", null, null, null, "numeric"], ["case_size", null, null, null, "numeric"], ["units_packaged", null, null, null, "numeric"], ["total_filled", null, null, null, "numeric"], ["total_units_filled", null, null, null, "numeric"], ["total_units", null, null, null, "numeric"], ["total_bulk", null, null, null, "numeric"], ["total_gram_equivalent", null, null, null, "numeric"], ["tac_pct", null, null, null, "numeric"], ["thc_pct", null, null, null, "numeric"], ["thca_pct", null, null, null, "numeric"], ["cannabinoid_reported", null, null, null, "text"], ["terpene_pct", null, null, null, "numeric"], ["terpene_status", null, null, null, "text"], ["creation_date", null, null, null, "date"], ["expiration_date", null, null, null, "date"], ["days_to_expiry_per_sheet", null, null, null, "integer"], ["days_to_expiry_recomputed", null, null, null, "integer"], ["expiry_bucket", null, null, null, "text"], ["expiry_flag_per_sheet", null, null, null, "text"], ["threshold_units", null, null, null, "numeric"], ["low_stock_flag_per_sheet", null, null, null, "text"], ["low_stock_recomputed", null, null, null, "boolean"], ["coa_link", null, null, null, "text"], ["has_coa_link", null, null, null, "boolean"], ["inventory_check", null, null, null, "text"], ["location", null, null, null, "text"], ["notes", null, null, null, "text"], ["metrc_existence", null, null, null, "text"], ["metrc_quantity_check", null, null, null, "text"], ["metrc_identity_check", null, null, null, "text"], ["metrc_qty", null, null, null, "numeric"], ["metrc_uom", null, null, null, "text"], ["comparison_basis", null, null, null, "text"], ["sheet_comparable", null, null, null, "numeric"], ["sales_confidence", null, null, null, "text"], ["source_sheet", null, null, null, "text"], ["source_row", null, null, null, "integer"], ["sheet_key", null, null, null, "text"], ["source_file_id"