INSERT INTO tg_quantity_preflight(name,definition_hash,owner_name,acl,options,extra,relation_kind,build_order,populated) VALUES ('"public"."v_gap_system"','1a1909888d862e085588ab89d642ba7c','postgres','{postgres=arwdDxtm/postgres,anon=xtm/postgres,authenticated=arwdxtm/postgres,service_role=arwdDxtm/postgres,tg_desktop_reader=r/postgres,grok_writer=arwd/postgres,supabase_read_only_user=r/postgres}',ARRAY['security_invoker=true']::text[],'{"comment": "System and pipeline gaps (owner ledger family 12 plus the five structural gaps he formalised 19 Aug 2026): the OS monitoring its own build completeness on the same board as its data \u2014 missing event types, failed imports, undated dashboard figures, QuickBooks absent, Apex inventory unsynced, documents unconsolidated. An unfinished spine is a compliance risk exactly like a missing manifest, and putting it here means it cannot be quietly deprioritised. Each row disappears by itself the day the thing is built. Agent I.", "columns": [["gap_type", null, null, null, "text"], ["severity", null, null, null, "text"], ["subject", null, null, null, "text"], ["description", null, null, null, "text"], ["required_action", null, null, null, "text"]], "indexes": []}'::jsonb,'v',202,true);

