INSERT INTO tg_quantity_preflight(name,definition_hash,owner_name,acl,options,extra,relation_kind,build_order,populated) VALUES ('"public"."v_tag_evidence"','80f80b0cedbdd397eeec33fcdbeecc33','postgres','{postgres=arwdDxtm/postgres,anon=xtm/postgres,authenticated=arwdxtm/postgres,service_role=arwdDxtm/postgres,tg_desktop_reader=r/postgres,grok_writer=arwd/postgres,supabase_read_only_user=r/postgres}',ARRAY['security_invoker=true']::text[],'{"comment": "Certificate and manifest evidence per tag \u2014 the object the front end should read INSTEAD of mv_tag_evidence. Columns 1-15 are a drop-in match for that matview so the repoint is a one-word change in dashkit.jsx and wcanvas-data.js. It exists because mv_tag_evidence inherits certificates through lineage but never consults metrc_lab_results.document_file_id, so 935 tags holding a fetched and parsed certificate read as having none. evidence_source moves upward only and now has FIVE values: the four original, plus \"certificate on file\" for a depth-0 bridge tag. That fifth value exists because \"direct\" already means the document names the tag \u2014 measured across the 160 such tags, NONE is named by its document and SEVEN are named by a certificate printing a different tag, so calling them direct would put two populations under one word. \"inherited\" always carries a non-null certificate_inherited_from, because a depth-0 bridge tag inherited nothing. certificate_grade carries the real basis, including the case where the certificate is genuine and the document does not print the tag. certificate_client is verbatim and carries NO ownership verdict: 15 certificates read Zen MA against our own MP281909.", "columns": [["tag", null, null, null, "text"], ["item_name", null, null, null, "text"], ["lab_testing_state", null, null, null, "text"], ["evidence_source", null, null, null, "text"], ["certificate_id", null, null, null, "text"], ["certificate_date", null, null, null, "text"], ["total_thc", null, null, null, "numeric"], ["certificate_inherited_from", null, null, null, "text"], ["certificate_document", null, null, null, "text"], ["lab_result_date", null, null, null, "date"], ["lab_name", null, null, null, "text"], ["manifest_number", null, null, null, "text"], ["manifest_document", null, null, null, "text"], ["why_no_certificate", null, null, null, "text"], ["why_no_manifest", null, null, null, "text"], ["certificate_grade", null, null, null, "text"], ["certificate_hops", null, null, null, "integer"], ["certificate_client", null, null, null, "text"], ["certificate_client_license", null, null, null, "text"]], "indexes": []}'::jsonb,'v',50,true);

