INSERT INTO tg_quantity_preflight(name,definition_hash,owner_name,acl,options,extra,relation_kind,build_order,populated) VALUES ('"public"."v_outbound_balance"','8c97458006f044b9038b87cef20f126f','postgres','{postgres=arwdDxtm/postgres,anon=xtm/postgres,authenticated=arwdxtm/postgres,service_role=arwdDxtm/postgres,tg_desktop_reader=r/postgres,grok_writer=arwd/postgres,supabase_read_only_user=r/postgres}',ARRAY['security_invoker=true']::text[],'{"comment": "The outbound control total. Every pound that left our licences, split four ways \u2014 internal moves, transport legs, laboratory samples, genuine sales \u2014 which sum to the total exactly. Built 18 Aug 2026 after transport legs and lab samples were found being counted as unsold shipments on two Command Center tiles. If these four ever stop adding up, something has been classified twice or not at all. Agent I.", "columns": [["stream", null, null, null, "text"], ["ord", null, null, null, "integer"], ["lb", null, null, null, "numeric"], ["tags", null, null, null, "bigint"], ["why", null, null, null, "text"]], "indexes": []}'::jsonb,'v',103,true);

