DO $tg_precision_capture$
DECLARE r record; c record; sample boolean;
BEGIN
 FOR r IN SELECT * FROM tg_quantity_preflight LOOP
  PERFORM set_config('application_name','tg precision precheck '||r.name,true);
  SELECT pg_get_viewdef(oid,true) def,pg_get_userbyid(relowner) own,relacl::text acl,reloptions opts,relkind::text kind,relispopulated populated INTO c FROM pg_class WHERE oid=to_regclass(r.name);
  IF c IS NULL OR md5(c.def)<>r.definition_hash OR c.own<>r.owner_name OR c.acl IS DISTINCT FROM r.acl OR c.opts IS DISTINCT FROM r.options OR c.kind<>r.relation_kind OR c.populated<>r.populated THEN RAISE EXCEPTION 'Dependency changed: %; re-rehearse',r.name; END IF;
  IF r.extra IS DISTINCT FROM jsonb_build_object('comment',obj_description(to_regclass(r.name),'pg_class'),'columns',(select jsonb_agg(jsonb_build_array(a.attname,col_description(a.attrelid,a.attnum),a.attacl,pg_get_expr(d.adbin,d.adrelid),format_type(a.atttypid,a.atttypmod)) order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=to_regclass(r.name) and a.attnum>0 and not a.attisdropped),'indexes',coalesce((select jsonb_agg(jsonb_build_array(ci.relname,pg_get_indexdef(i.indexrelid),obj_description(ci.oid,'pg_class'),i.indisclustered,i.indisvalid,i.indisready) order by ci.relname) from pg_index i join pg_class ci on ci.oid=i.indexrelid where i.indrelid=to_regclass(r.name)),'[]'::jsonb)) THEN RAISE EXCEPTION 'Dependency column/comment/index metadata changed: %; re-rehearse',r.name; END IF;
  -- This UNION ALL panel always has its literal ord=1 row. Selecting it prunes unrelated report totals during this row-presence check.
  EXECUTE 'select exists(select 1 from '||r.name||case when r.name='"public"."v_forensic_audit_panel_live"' then ' where ord=1' else '' end||' limit 1)' INTO sample;
  UPDATE tg_quantity_preflight SET had_row=sample,definition=c.def WHERE name=r.name;
 END LOOP;
EXCEPTION WHEN query_canceled THEN RAISE EXCEPTION 'Precision read check timed out at %',r.name;
END $tg_precision_capture$;
-- The existing guard explicitly permits a transaction-local, fully rebuilt view
-- migration with tg.allow_drop=yes. The guard itself remains installed and enabled.
SELECT set_config('tg.allow_drop','yes',true);


DO $tg_cycle_equivalence$ BEGIN IF EXISTS (WITH candidate AS ( SELECT e.tag,
    e.item_name,
    e.lab_testing_state,
        CASE
            WHEN e.evidence_source = ANY (ARRAY['direct'::text, 'inherited'::text]) THEN e.evidence_source
            WHEN cr.package_tag IS NULL THEN e.evidence_source
            WHEN cr.found_at_depth = 0 THEN 'certificate on file'::text
            ELSE 'inherited'::text
        END AS evidence_source,
    COALESCE(e.certificate_id, b.lab_report_id) AS certificate_id,
    COALESCE(e.certificate_date, b.report_date) AS certificate_date,
    COALESCE(e.total_thc, b.total_thc) AS total_thc,
        CASE
            WHEN e.certificate_inherited_from IS NOT NULL THEN e.certificate_inherited_from
            WHEN cr.found_at_depth > 0 THEN cr.certificate_on_package
            ELSE NULL::text
        END AS certificate_inherited_from,
    COALESCE(e.certificate_document, b.storage_path) AS certificate_document,
    e.lab_result_date,
    e.lab_name,
    e.manifest_number,
    e.manifest_document,
        CASE
            WHEN e.evidence_source = ANY (ARRAY['direct'::text, 'inherited'::text]) THEN e.why_no_certificate
            WHEN b.storage_path IS NOT NULL THEN NULL::text
            ELSE e.why_no_certificate
        END AS why_no_certificate,
    e.why_no_manifest,
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM coa_extract c
              WHERE c.package_tag = e.tag)) THEN 'direct — the certificate document names this tag'::text
            WHEN e.certificate_inherited_from IS NOT NULL THEN 'inherited — a parsed certificate names ancestor '::text || e.certificate_inherited_from
            WHEN cr.found_at_depth = 0 AND b.printed_tag IS NOT NULL AND b.printed_tag <> e.tag THEN ('certificate on file — Metrc''s lab result for this tag names this certificate, and the document itself prints a DIFFERENT tag, '::text || b.printed_tag) || '. One certificate covers a whole batch; this tag is a member the document does not list by name.'::text
            WHEN cr.found_at_depth = 0 THEN 'certificate on file — Metrc''s lab result for this tag names this certificate; the document itself prints no tag we could read, so it does not name this package'::text
            WHEN cr.found_at_depth > 0 THEN ('inherited via Metrc — the lab result for ancestor '::text || cr.certificate_on_package) || ' names this certificate'::text
            WHEN e.evidence_source = 'lab result only'::text THEN 'lab result only — Metrc holds the result and that laboratory attached no certificate document'::text
            ELSE 'none — no certificate on this tag, its lineage, or any Metrc lab result'::text
        END AS certificate_grade,
    cr.found_at_depth AS certificate_hops,
    cr.cert_client AS certificate_client,
    cr.cert_license AS certificate_client_license
   FROM mv_tag_evidence e
     LEFT JOIN mv_certificate_resolved cr ON cr.package_tag = e.tag
     LEFT JOIN LATERAL ( SELECT d.storage_path,
            c.lab_report_id,
            c.report_date,
            c.total_thc,
            c.package_tag_on_document AS printed_tag
           FROM metrc_lab_results l
             JOIN metrc_documents d ON d.metrc_id = l.document_file_id AND d.doc_type = 'coa'::text
             LEFT JOIN coa_extract c ON c.document_id = l.document_file_id
          WHERE l.package_tag = cr.certificate_on_package AND l.document_file_id IS NOT NULL
         LIMIT 1) b ON true) (SELECT * FROM public.v_tag_evidence EXCEPT ALL SELECT * FROM candidate) UNION ALL (SELECT * FROM candidate EXCEPT ALL SELECT * FROM public.v_tag_evidence)) THEN RAISE EXCEPTION 'Cycle-cut candidate changes evidence rows'; END IF; END $tg_cycle_equivalence$;

LOCK TABLE public.metrc_packages IN ACCESS EXCLUSIVE MODE;

DO $tg_precision_guard$
BEGIN
 IF (select format_type(atttypid,atttypmod) from pg_attribute where attrelid='public.metrc_packages'::regclass and attname='quantity') <> 'numeric(14,3)' THEN RAISE EXCEPTION 'Quantity schema changed; re-rehearse'; END IF;
 IF (select count(*) from public.metrc_packages where raw->>'Quantity' is not null and quantity<>(raw->>'Quantity')::numeric) <> 6 THEN RAISE EXCEPTION 'Quantity discrepancy population changed; obtain new evidence'; END IF;
 IF (select md5(string_agg(jsonb_build_object('id',id,'license',license,'quantity',quantity,'raw',raw)::text,'' order by id)) from public.metrc_packages where raw->>'Quantity' is not null and quantity<>(raw->>'Quantity')::numeric) IS DISTINCT FROM 'e22944a53f041c4d9b9fb39a7fb6b1f0' THEN RAISE EXCEPTION 'Quantity source records changed; obtain new evidence'; END IF;
END $tg_precision_guard$;

CREATE OR REPLACE VIEW public.v_tag_evidence WITH (security_invoker=true) AS  SELECT e.tag,
    e.item_name,
    e.lab_testing_state,
        CASE
            WHEN e.evidence_source = ANY (ARRAY['direct'::text, 'inherited'::text]) THEN e.evidence_source
            WHEN cr.package_tag IS NULL THEN e.evidence_source
            WHEN cr.found_at_depth = 0 THEN 'certificate on file'::text
            ELSE 'inherited'::text
        END AS evidence_source,
    COALESCE(e.certificate_id, b.lab_report_id) AS certificate_id,
    COALESCE(e.certificate_date, b.report_date) AS certificate_date,
    COALESCE(e.total_thc, b.total_thc) AS total_thc,
        CASE
            WHEN e.certificate_inherited_from IS NOT NULL THEN e.certificate_inherited_from
            WHEN cr.found_at_depth > 0 THEN cr.certificate_on_package
            ELSE NULL::text
        END AS certificate_inherited_from,
    COALESCE(e.certificate_document, b.storage_path) AS certificate_document,
    e.lab_result_date,
    e.lab_name,
    e.manifest_number,
    e.manifest_document,
        CASE
            WHEN e.evidence_source = ANY (ARRAY['direct'::text, 'inherited'::text]) THEN e.why_no_certificate
            WHEN b.storage_path IS NOT NULL THEN NULL::text
            ELSE e.why_no_certificate
        END AS why_no_certificate,
    e.why_no_manifest,
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM coa_extract c
              WHERE c.package_tag = e.tag)) THEN 'direct — the certificate document names this tag'::text
            WHEN e.certificate_inherited_from IS NOT NULL THEN 'inherited — a parsed certificate names ancestor '::text || e.certificate_inherited_from
            WHEN cr.found_at_depth = 0 AND b.printed_tag IS NOT NULL AND b.printed_tag <> e.tag THEN ('certificate on file — Metrc''s lab result for this tag names this certificate, and the document itself prints a DIFFERENT tag, '::text || b.printed_tag) || '. One certificate covers a whole batch; this tag is a member the document does not list by name.'::text
            WHEN cr.found_at_depth = 0 THEN 'certificate on file — Metrc''s lab result for this tag names this certificate; the document itself prints no tag we could read, so it does not name this package'::text
            WHEN cr.found_at_depth > 0 THEN ('inherited via Metrc — the lab result for ancestor '::text || cr.certificate_on_package) || ' names this certificate'::text
            WHEN e.evidence_source = 'lab result only'::text THEN 'lab result only — Metrc holds the result and that laboratory attached no certificate document'::text
            ELSE 'none — no certificate on this tag, its lineage, or any Metrc lab result'::text
        END AS certificate_grade,
    cr.found_at_depth AS certificate_hops,
    cr.cert_client AS certificate_client,
    cr.cert_license AS certificate_client_license
   FROM mv_tag_evidence e
     LEFT JOIN mv_certificate_resolved cr ON cr.package_tag = e.tag
     LEFT JOIN LATERAL ( SELECT d.storage_path,
            c.lab_report_id,
            c.report_date,
            c.total_thc,
            c.package_tag_on_document AS printed_tag
           FROM metrc_lab_results l
             JOIN metrc_documents d ON d.metrc_id = l.document_file_id AND d.doc_type = 'coa'::text
             LEFT JOIN coa_extract c ON c.document_id = l.document_file_id
          WHERE l.package_tag = cr.certificate_on_package AND l.document_file_id IS NOT NULL
         LIMIT 1) b ON true;

DROP FUNCTION public.f_drill_stays(text,date,date);

DO $tg_precision_drop$
DECLARE r record;
BEGIN
 FOR r IN SELECT * FROM tg_quantity_preflight ORDER BY build_order DESC LOOP
  EXECUTE 'DROP '||(case when r.relation_kind='m' then 'MATERIALIZED VIEW' else 'VIEW' end)||' '||r.name;
 END LOOP;
END $tg_precision_drop$;

ALTER TABLE public.metrc_packages ALTER COLUMN quantity TYPE numeric;
UPDATE public.metrc_packages SET quantity=(raw->>'Quantity')::numeric
 WHERE raw->>'Quantity' is not null AND quantity<>(raw->>'Quantity')::numeric;
ANALYZE public.metrc_packages;


-- Latest scheduled refreshes of two affected materialized views took 37s and 19s.
-- The queued runner bounds this complete transaction at 15 minutes.

DO $tg_precision_rebuild$
DECLARE r record; a record; item jsonb; object_kind text; definition text; role_list text;
BEGIN
 FOR r IN SELECT * FROM tg_quantity_preflight ORDER BY build_order LOOP
  PERFORM set_config('application_name','tg precision rebuild '||r.name,true);
  object_kind:=case when r.relation_kind='m' then 'MATERIALIZED VIEW' else 'VIEW' end;
  definition:=regexp_replace(r.definition,';[[:space:]]*$','');
  IF r.name='"public"."v_tag_evidence"' THEN definition:=replace(definition,'LEFT JOIN v_certificate_resolved cr','LEFT JOIN mv_certificate_resolved cr'); END IF;
  EXECUTE 'CREATE '||object_kind||' '||r.name||case when r.options is not null then ' WITH ('||array_to_string(r.options,',')||')' else '' end||' AS '||definition||case when r.relation_kind='m' then case when r.populated then ' WITH DATA' else ' WITH NO DATA' end else '' end;
  EXECUTE format('ALTER %s %s OWNER TO %I',object_kind,r.name,r.owner_name);
  -- Restore exactly the prior options and grants, including existing issue-queue
  -- owner execution. The existing f_xq_reader authorization predicates remain.
  IF r.options is not null THEN EXECUTE 'ALTER '||object_kind||' '||r.name||' SET ('||array_to_string(r.options,',')||')'; END IF;
  SELECT string_agg(case when grantee=0 then 'PUBLIC' else quote_ident(pg_get_userbyid(grantee)) end,',') INTO role_list FROM (SELECT distinct grantee FROM pg_class c CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a WHERE c.oid=to_regclass(r.name) UNION SELECT 0::oid) x;
  EXECUTE 'REVOKE ALL ON TABLE '||r.name||' FROM '||role_list;
  FOR a IN SELECT * FROM aclexplode(r.acl::aclitem[]) LOOP
   EXECUTE 'GRANT '||a.privilege_type||' ON TABLE '||r.name||' TO '||case when a.grantee=0 then 'PUBLIC' else quote_ident(pg_get_userbyid(a.grantee)) end||case when a.is_grantable then ' WITH GRANT OPTION' else '' end;
  END LOOP;
  IF r.extra->>'comment' is not null THEN EXECUTE format('COMMENT ON %s %s IS %L',object_kind,r.name,r.extra->>'comment'); END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(r.extra->'columns') LOOP
   IF item->>1 is not null THEN EXECUTE format('COMMENT ON COLUMN %s.%I IS %L',r.name,item->>0,item->>1); END IF;
   IF item->>3 is not null THEN EXECUTE format('ALTER VIEW %s ALTER COLUMN %I SET DEFAULT %s',r.name,item->>0,item->>3); END IF;
  END LOOP;
  FOR item IN SELECT value FROM jsonb_array_elements(r.extra->'indexes') LOOP
   EXECUTE item->>1;
   IF item->>2 is not null THEN EXECUTE format('COMMENT ON INDEX public.%I IS %L',item->>0,item->>2); END IF;
   IF (item->>3)::boolean THEN EXECUTE format('ALTER MATERIALIZED VIEW %s CLUSTER ON %I',r.name,item->>0); END IF;
  END LOOP;
  IF r.relation_kind='m' AND r.populated THEN EXECUTE 'ANALYZE '||r.name; END IF;
 END LOOP;
EXCEPTION WHEN query_canceled THEN RAISE EXCEPTION 'Precision rebuild timed out at %',r.name;
END $tg_precision_rebuild$;


CREATE OR REPLACE FUNCTION public.f_drill_stays(p_tag text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS SETOF v_tag_stay
 LANGUAGE sql
 STABLE PARALLEL SAFE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select * from public.v_tag_stay s
  where s.tag = p_tag
    /* OVERLAP, not start-date: a stay that began before the window and is
       still running IS the current location and must show. */
    and (p_from is null or coalesce(s.end_timestamp, now()) >= p_from::timestamptz)
    and (p_to   is null or s.start_timestamp < (p_to + 1)::timestamptz)
  order by s.stay_no;
$function$;

ALTER FUNCTION public.f_drill_stays(text,date,date) OWNER TO postgres;

REVOKE ALL ON FUNCTION public.f_drill_stays(text,date,date) FROM "anon","authenticated","grok_writer","postgres","service_role","supabase_read_only_user","tg_desktop_reader",PUBLIC;

GRANT EXECUTE ON FUNCTION public.f_drill_stays(text,date,date) TO "postgres";

GRANT EXECUTE ON FUNCTION public.f_drill_stays(text,date,date) TO "authenticated";

GRANT EXECUTE ON FUNCTION public.f_drill_stays(text,date,date) TO "service_role";

GRANT EXECUTE ON FUNCTION public.f_drill_stays(text,date,date) TO "tg_desktop_reader";

COMMENT ON FUNCTION public.f_drill_stays(text,date,date) IS 'One tag''s room/stage stays, windowed by OVERLAP so a stay that began before the window and is still open still shows — it is where the material is. Agent I.';

DO $tg_function_guard$ BEGIN IF pg_get_functiondef('public.f_drill_stays(text,date,date)'::regprocedure) IS DISTINCT FROM 'CREATE OR REPLACE FUNCTION public.f_drill_stays(p_tag text, p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date)
 RETURNS SETOF v_tag_stay
 LANGUAGE sql
 STABLE PARALLEL SAFE
 SET search_path TO ''public'', ''pg_temp''
AS $function$
  select * from public.v_tag_stay s
  where s.tag = p_tag
    /* OVERLAP, not start-date: a stay that began before the window and is
       still running IS the current location and must show. */
    and (p_from is null or coalesce(s.end_timestamp, now()) >= p_from::timestamptz)
    and (p_to   is null or s.start_timestamp < (p_to + 1)::timestamptz)
  order by s.stay_no;
$function$
' OR (select proacl::text from pg_proc where oid='public.f_drill_stays(text,date,date)'::regprocedure) IS DISTINCT FROM '{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres,tg_desktop_reader=X/postgres}' OR obj_description('public.f_drill_stays(text,date,date)'::regprocedure,'pg_proc') IS DISTINCT FROM 'One tag''s room/stage stays, windowed by OVERLAP so a stay that began before the window and is still open still shows — it is where the material is. Agent I.' THEN RAISE EXCEPTION 'Drill function changed or was not restored exactly'; END IF; END $tg_function_guard$;

DO $tg_precision_verify$
DECLARE r record; c record; sample boolean;
BEGIN
 IF (select format_type(atttypid,atttypmod) from pg_attribute where attrelid='public.metrc_packages'::regclass and attname='quantity') <> 'numeric' THEN RAISE EXCEPTION 'Quantity is still constrained'; END IF;
 IF EXISTS(select 1 from public.metrc_packages where raw->>'Quantity' is not null and quantity<>(raw->>'Quantity')::numeric) THEN RAISE EXCEPTION 'Source quantity mismatch remains'; END IF;
 IF EXISTS(select 1 from tg_quantity_changed o left join public.metrc_packages p using(id) where p.id is null or p.raw is distinct from o.raw or p.license is distinct from o.license or p.quantity is distinct from (o.raw->>'Quantity')::numeric) THEN RAISE EXCEPTION 'Repaired record provenance or exact value differs'; END IF;
 FOR r IN SELECT * FROM tg_quantity_preflight LOOP
  PERFORM set_config('application_name','tg precision finalcheck '||r.name,true);
  SELECT pg_get_userbyid(relowner) own,relacl::text acl,reloptions opts INTO c FROM pg_class WHERE oid=to_regclass(r.name);
  IF c IS NULL OR c.own<>r.owner_name OR c.opts IS DISTINCT FROM r.options THEN RAISE EXCEPTION 'Restored dependency metadata differs: %',r.name; END IF;
  IF r.extra IS DISTINCT FROM jsonb_build_object('comment',obj_description(to_regclass(r.name),'pg_class'),'columns',(select jsonb_agg(jsonb_build_array(a.attname,col_description(a.attrelid,a.attnum),a.attacl,pg_get_expr(d.adbin,d.adrelid),case when r.extra->'columns'->(a.attnum-1)->>4='numeric(14,3)' and format_type(a.atttypid,a.atttypmod)='numeric' then 'numeric(14,3)' else format_type(a.atttypid,a.atttypmod) end) order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=to_regclass(r.name) and a.attnum>0 and not a.attisdropped),'indexes',coalesce((select jsonb_agg(jsonb_build_array(ci.relname,pg_get_indexdef(i.indexrelid),obj_description(ci.oid,'pg_class'),i.indisclustered,i.indisvalid,i.indisready) order by ci.relname) from pg_index i join pg_class ci on ci.oid=i.indexrelid where i.indrelid=to_regclass(r.name)),'[]'::jsonb)) THEN RAISE EXCEPTION 'Restored columns/comments/indexes differ: %',r.name; END IF;
  IF EXISTS((SELECT grantor,grantee,privilege_type,is_grantable FROM aclexplode(r.acl::aclitem[]) EXCEPT SELECT grantor,grantee,privilege_type,is_grantable FROM aclexplode(c.acl::aclitem[])) UNION ALL (SELECT grantor,grantee,privilege_type,is_grantable FROM aclexplode(c.acl::aclitem[]) EXCEPT SELECT grantor,grantee,privilege_type,is_grantable FROM aclexplode(r.acl::aclitem[]))) THEN RAISE EXCEPTION 'Restored permissions differ: %',r.name; END IF;
  -- This UNION ALL panel always has its literal ord=1 row. Selecting it prunes unrelated report totals during this row-presence check.
  EXECUTE 'select exists(select 1 from '||r.name||case when r.name='"public"."v_forensic_audit_panel_live"' then ' where ord=1' else '' end||' limit 1)' INTO sample;
  IF r.had_row AND NOT sample THEN RAISE EXCEPTION 'Previously populated dependency became empty: %',r.name; END IF;
 END LOOP;
EXCEPTION WHEN query_canceled THEN RAISE EXCEPTION 'Precision final check timed out at %',r.name;
END $tg_precision_verify$;
SELECT set_config('tg.allow_drop','',true);
NOTIFY pgrst,'reload schema';

$tg_repair_body$::text;
$tg_sql_source$;

CREATE FUNCTION tg_maintenance.run_metrc_precision_v2() RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_catalog,tg_maintenance AS $tg_runner$
DECLARE r tg_maintenance.metrc_quantity_precision_run%rowtype; body text; result jsonb; ctx text;
BEGIN
 SELECT * INTO STRICT r FROM tg_maintenance.metrc_quantity_precision_run WHERE run_key='metrc-quantity-20260912-v2' FOR UPDATE;
 IF EXISTS(SELECT 1 FROM cron.job WHERE jobname=r.job_name) THEN PERFORM cron.unschedule(r.job_name); END IF;
 IF r.status IN('completed','failed','expired') THEN RETURN to_jsonb(r); END IF;
 IF clock_timestamp()>r.expires_at THEN
  UPDATE tg_maintenance.metrc_quantity_precision_run SET status='expired',finished_at=clock_timestamp(),error='Job expired before starting; no repair attempted' WHERE run_key=r.run_key;
 ELSE
  UPDATE tg_maintenance.metrc_quantity_precision_run SET status='running',started_at=clock_timestamp() WHERE run_key=r.run_key;
  BEGIN
   body:=tg_maintenance.metrc_precision_sql_v2();
   IF encode(sha256(convert_to(body,'UTF8')),'hex') IS DISTINCT FROM r.repair_sha256 THEN RAISE EXCEPTION 'Queued repair hash changed'; END IF;
   EXECUTE body;
   SELECT jsonb_build_object('scope','saved-source quantity precision; not whole-population certification','verified_at',clock_timestamp(),'quantity_type',(select format_type(atttypid,atttypmod) from pg_attribute where attrelid='public.metrc_packages'::regclass and attname='quantity'),'remaining_source_quantity_mismatches',(select count(*) from public.metrc_packages where raw->>'Quantity' is not null and quantity is distinct from (raw->>'Quantity')::numeric),'repaired_rows',(select count(*) from pg_temp.tg_quantity_changed),'verified_dependencies',(select count(*) from pg_temp.tg_quantity_preflight),'repair_sha256',r.repair_sha256) INTO result;
   IF result->>'quantity_type'<>'numeric' OR (result->>'remaining_source_quantity_mismatches')::int<>0 OR (result->>'repaired_rows')::int<>6 OR (result->>'verified_dependencies')::int<>204 THEN RAISE EXCEPTION 'Final precision receipt does not reconcile'; END IF;
   UPDATE tg_maintenance.metrc_quantity_precision_run SET status='completed',finished_at=clock_timestamp(),receipt=result WHERE run_key=r.run_key;
  EXCEPTION WHEN query_canceled THEN
   GET STACKED DIAGNOSTICS ctx=PG_EXCEPTION_CONTEXT;
   UPDATE tg_maintenance.metrc_quantity_precision_run SET status='failed',finished_at=clock_timestamp(),error=SQLSTATE||': '||SQLERRM,error_context=left(ctx,3000) WHERE run_key=r.run_key;
  WHEN OTHERS THEN
   GET STACKED DIAGNOSTICS ctx=PG_EXCEPTION_CONTEXT;
   UPDATE tg_maintenance.metrc_quantity_precision_run SET status='failed',finished_at=clock_timestamp(),error=SQLSTATE||': '||SQLERRM,error_context=left(ctx,3000) WHERE run_key=r.run_key;
  END;
 END IF;
 SELECT to_jsonb(x) INTO result FROM tg_maintenance.metrc_quantity_precision_run x WHERE run_key=r.run_key;
 RETURN result;
END $tg_runner$;
REVOKE ALL ON FUNCTION tg_maintenance.metrc_precision_sql_v2(),tg_maintenance.run_metrc_precision_v2() FROM PUBLIC,anon,authenticated,service_role;

DO $tg_queue$
DECLARE scheduled timestamptz:=date_trunc('minute',clock_timestamp())+interval '2 minutes'; job_name text:='gpt_metrc_quantity_precision_20260912_v2'; v_job_id bigint;
BEGIN
 IF EXISTS(SELECT 1 FROM cron.job WHERE jobname=job_name) THEN RAISE EXCEPTION 'Precision job name already exists'; END IF;
 INSERT INTO tg_maintenance.metrc_quantity_precision_run(run_key,status,scheduled_at,expires_at,repair_sha256,job_name)
 VALUES('metrc-quantity-20260912-v2','pending',scheduled,clock_timestamp()+interval '20 minutes',encode(sha256(convert_to(tg_maintenance.metrc_precision_sql_v2(),'UTF8')),'hex'),job_name);
 SELECT cron.schedule(job_name,to_char(scheduled AT TIME ZONE coalesce(nullif(current_setting('cron.timezone',true),''),'GMT'),'MI HH24 DD MM')||' *','SET statement_timeout=''15min''; SET lock_timeout=''3s''; SELECT tg_maintenance.run_metrc_precision_v2();') INTO v_job_id;
 UPDATE tg_maintenance.metrc_quantity_precision_run SET job_id=v_job_id WHERE run_key='metrc-quantity-20260912-v2';
END $tg_queue$;
